import type {AcademyLesson} from './types';
export const interpersonal:AcademyLesson[]=[
{id:'guilt-tripping',number:10,module:'B',status:'full',title:'Guilt-Tripping',definition:'Guilt-tripping uses a sense of wrongdoing or obligation to pressure someone into a choice, rather than discussing the request on its merits.',explanation:'Guilt can be useful when it draws attention to harm we actually caused. Pressure becomes concerning when ordinary limits are repeatedly treated as proof of moral failure. A parent may genuinely miss an adult child and still express that need unfairly. A friend can have a legitimate grievance without being entitled to money, time, or agreement. Evaluate the specific obligation: was there an agreement, what can reasonably be repaired, and does the requested response fit the harm? Gratitude for past help is not unlimited consent to future demands.',mechanism:'Belonging and reciprocity matter to people. A message linking refusal with being selfish can make compliance feel like the quickest way to restore a valued identity. Relief after giving in may reinforce the pattern. This does not prove deliberate planning; learned family communication can reproduce pressure without conscious strategy.',examples:['Alia cannot attend a family meal because of an exam. Her uncle repeatedly says she has forgotten the people who raised her, although she offers a call after studying. The request becomes a test of loyalty.','Ken forgot a promised ride and apologises. His friend asks him to cover the actual replacement fare. Proportionate repair for a broken agreement differs from claiming that Ken must now provide rides indefinitely.'],dialogue:['Uncle: “After everything we did, you cannot give us one evening?”','Alia: “I appreciate your support and need to prepare for this exam.”','Alia: “I can call Sunday, but I cannot travel tonight.”'],notice:'Look for recurring loyalty tests, unrelated historical debts, and whether a reasonable alternative is considered. Notice whether disappointment is expressed as a feeling or converted into a demand. Your own guilt is information to examine, not proof that either person is right.',not:'Expressing hurt, asking for accountability, or reminding someone of a real promise is not automatically guilt-tripping. People may communicate poorly in a difficult moment and then accept clarification.',consequences:'Repeated moral pressure can make rest, financial limits, or independent choices feel shameful. Resentment may build while the underlying need remains unspoken. Calling every complaint manipulation can also prevent needed repair.',tips:'Write down the actual promise and the requested remedy. Acknowledge legitimate impact, offer proportionate repair when appropriate, and separate appreciation from consent. Practise one brief response rather than defending your entire character. Where refusal brings threats or dependency risks, seek support before confronting the pattern.',alternative:'“I miss you and would like to plan a visit” communicates a need without claiming ownership of another person’s time. A listener can care and still negotiate a feasible date.',takeaways:['Guilt is not proof of an obligation.','Accountability should connect to a specific action.','Gratitude does not create unlimited debt.'],check:{difficulty:'Intermediate',prompt:'Which request is most consistent with proportionate accountability rather than guilt pressure?',options:['Pay the actual replacement fare after breaking an agreed transport promise.','Prove your friendship by lending money forever.','Cancel every future plan because you once forgot a visit.'],correct:0,explanation:'A specific remedy connected to a real agreement differs from indefinite loyalty demands. Feasibility and context still matter.'},related:['manipulation-academy','reciprocity','boundaries-academy'],references:['cci','coercion'],evidence:'Guilt and interpersonal influence are established research topics; “guilt-tripping” is a descriptive everyday label, not a diagnosis.'},
{id:'love-bombing',number:11,module:'B',status:'full',title:'Love Bombing',definition:'Love bombing is a popular label for overwhelming affection or attention that may be part of a controlling relationship pattern; intensity alone does not establish that pattern.',explanation:'Early excitement can involve frequent messages, gifts, and hopes about a shared future. These behaviours also occur in healthy relationships. The more useful question is whether warmth becomes conditional on rapid commitment, isolation, or surrendering limits. A costly gift may feel generous until it is invoked as a debt. We cannot reliably infer a hidden plan from romance, enthusiasm, or a short transcript. Keep the evaluation behavioural: how does the person respond to a slower pace, independent friendships, and an ordinary no? A label should not replace that evidence.',mechanism:'Attention can strengthen attachment and perceived obligation. Rapid exclusivity may reduce time to evaluate compatibility or seek outside perspectives. If warmth alternates with withdrawal after refusal, compliance may seem like the route back to closeness. These are plausible processes, not a unique scientifically validated sequence that every relationship follows.',examples:['Within a week, Jules sends expensive presents and asks Mira to move in. When Mira asks for time, Jules insults her friends and demands passwords as proof of love. The reaction to limits is more concerning than the gifts alone.','Two people exchange enthusiastic messages, then agree to fewer calls during exams. They keep their separate friendships. Similar initial intensity has a different context and trajectory.'],dialogue:['Mira: “I enjoy seeing you and do not want to move in yet.”','Jules: “After these gifts, you owe me commitment.”','Mira: “A gift does not decide my living arrangements.”'],notice:'Look for pressure to accelerate, demands for access, dismissal of outside relationships, and punishment when affection is not reciprocated in the requested way. Consider duration, repetition, dependence, and whether apologies lead to changed conduct.',not:'Generosity, strong attraction, or different preferences for contact do not diagnose a personality disorder. A relationship developing quickly is not automatically abusive. Healthy people can misjudge intensity and then adjust respectfully.',consequences:'Unwanted acceleration may create financial or housing dependence before compatibility is understood. Someone may feel ungrateful for protecting privacy. Overusing the label can also make ordinary affection feel suspicious and distract from concrete risks.',tips:'Choose a pace that leaves time for independent decisions. Maintain ordinary supports and control over accounts and documents. Clarify whether a gift carries conditions before accepting when possible. If there are threats or surveillance, avoid treating a direct rejection as risk-free and seek confidential help.',alternative:'“I am excited about us, and we can take our time” leaves room for mutual consent. Genuine gifts do not become invoices for access or commitment.',takeaways:['Intensity alone is insufficient evidence.','The response to limits is important.','Gifts do not purchase consent.'],check:{difficulty:'Advanced',prompt:'Which observation most changes concern about intense early affection?',options:['The number of heart emojis.','Repeated retaliation when the other person asks to slow down.','The relationship began in spring.'],correct:1,explanation:'Retaliation for an ordinary limit indicates restriction of choice. Romantic enthusiasm alone cannot establish intent or abuse.'},related:['boundary-testing','coercion','intermittent-reinforcement'],references:['coercion','cci'],evidence:'Popular terminology with limited standardized measurement. Guidance about coercion supports evaluating control and retaliation, not diagnosing from affection.'},
{id:'emotional-blackmail',number:12,module:'B',status:'full',title:'Emotional Blackmail',definition:'Emotional blackmail is a descriptive term for using threatened emotional or relational consequences to force another person’s compliance.',explanation:'“Agree or I will punish you” can appear as a threat to expose private information, withdraw essential support, or blame someone for a crisis. The distress involved may be genuine; that does not automatically make the demanded action safe or fair. Separate the need for help from the proposed condition. A person is not required to provide passwords, money, sex, or secrecy in order to prove concern. Relationship decisions can also involve legitimate consequences: ending an incompatible relationship differs from repeatedly threatening abandonment to control ordinary independent choices. Context determines which account is better supported.',mechanism:'Fear, responsibility, and anticipated loss can narrow perceived alternatives. Compliance may stop an immediate threat while leaving the underlying danger unchanged. When threats repeatedly obtain the requested outcome, both parties can become caught in an increasingly rigid interaction. This explanation does not establish conscious intent or place responsibility for threats on the recipient.',examples:['A classmate says they will release private messages unless Farah writes their assignment. The threat uses privacy as leverage and adds academic risk.','A partner says they cannot remain in a relationship with repeated infidelity and discusses separation calmly. A specific limit about participation differs from using repeated breakup threats to control every friendship.'],dialogue:['Classmate: “Do my assignment or everyone sees those messages.”','Farah: “I need time before responding.”','Later Farah asks a trusted adviser about confidentiality and reporting options.'],notice:'Identify the demanded act, threatened consequence, credibility, and whether the person controls essential resources. Pay attention to secrecy demands and escalation after a refusal. A calm tone does not remove the threat; an emotional tone alone does not prove one.',not:'Expressing distress or deciding to leave a relationship is not automatically blackmail. A clinical diagnosis cannot be inferred from the phrase. Moral responsibility for another person’s entire emotional state is not transferred by an accusation.',consequences:'Threats may produce fear, isolation, unsafe compliance, or difficulty making independent decisions. Concealment can reduce access to support. Responding with counter-threats can increase risk rather than restore meaningful choice.',tips:'Do not promise unsafe compliance as your sole crisis strategy. If self-harm is threatened, take the risk seriously and seek appropriate urgent or professional support when safe; do not promise secrecy. Consider local specialist advice when privacy, housing, violence, or dependency is involved. Evidence preservation also needs a safety assessment.',alternative:'“I am struggling and need support” invites help without making one particular person responsible for obeying a demand. Legitimate limits specify one’s own participation rather than weaponising another person’s vulnerability.',takeaways:['A threat and a need are separate issues.','Concern does not require unsafe compliance.','Confidential support may be safer than confrontation.'],check:{difficulty:'Advanced',prompt:'A person threatens self-harm unless a partner shares passwords. What is the soundest principle?',options:['Share all passwords as the only safety plan.','Dismiss the threat because it involves pressure.','Take the risk seriously and seek suitable support without treating password access as owed.'],correct:2,explanation:'A threat deserves a safety response, but coerced account access is not a substitute for appropriate crisis support.'},related:['coercion','emotional-influence','isolation-control'],references:['coercion','cci'],evidence:'A popular descriptive framework rather than a diagnosis. Crisis responses require context-specific professional or emergency guidance.'},
{id:'silent-treatment',number:13,module:'B',status:'full',title:'Silent Treatment versus Healthy Space',definition:'Healthy space pauses an interaction to regulate or reflect; punitive silence uses withdrawal to punish, compel, or restrict another person. Silence alone does not reveal which is happening.',explanation:'People differ in how quickly they can discuss conflict. A person may become overwhelmed, need sleep, lack words, or reasonably decline an unsafe conversation. A useful pause communicates what can be communicated safely: the need for space, practical arrangements, and a feasible return point. Concern increases when silence repeatedly ends only after submission, blocks essential coordination, or accompanies threats and humiliation. Not everyone can name a return time immediately. Evaluate the pattern and its effects rather than imposing a universal deadline or assuming constant availability is a right.',mechanism:'Stepping away may reduce arousal and allow more considered responses. Unexplained exclusion can also increase anxiety and the urge to regain connection. If compliance consistently restores contact, the interaction can teach someone to abandon a limit. The same outward absence can therefore have different functions across situations.',examples:['During a tense discussion, Priya says she needs thirty minutes and returns to discuss the missed bill. The pause does not erase responsibility.','After their sibling refuses a loan, Arman ignores all household coordination for days and says contact will resume only when the money arrives. The explicit condition provides evidence of pressure.'],dialogue:['Priya: “I want to resolve this, but I cannot listen well right now.”','Lee: “Can we return after dinner?”','Priya: “Yes. I will still send the payment details we need today.”'],notice:'Ask whether the pause is communicated, whether urgent responsibilities remain covered, and what permits reconnection. Consider overwhelm, accessibility needs, work, prior conflict, and safety. Look for repeated patterns rather than reading intent from an unread-message indicator.',not:'No one owes immediate replies or contact with someone who threatens them. Blocking harassment or ending a relationship can be a protective boundary. A delayed reply is not enough to establish psychological abuse.',consequences:'A planned pause can prevent escalation. Repeated contingent withdrawal can increase insecurity and interfere with shared obligations. Demanding continuous contact can itself become controlling, even when framed as a wish for healthy communication.',tips:'In a low-risk relationship, agree in advance how pauses work and how essential information will be shared. State a realistic return time rather than promising what you cannot manage. If contact is unsafe, a supported separation or third-party coordination may be more appropriate than a reunion conversation.',alternative:'“I need space tonight; I will discuss the bill tomorrow” combines a limit with accountability. A listener can respect space while arranging practical matters separately and evaluating whether the pattern is sustainable.',takeaways:['Silence has multiple possible explanations.','Conditions for reconnection can reveal pressure.','Space and accountability can coexist.'],check:{difficulty:'Intermediate',prompt:'Which detail most supports interpreting a pause as healthy space?',options:['Contact resumes only after surrendering a boundary.','The person names a feasible return point and follows through.','The pause lasts exactly one universal approved duration.'],correct:1,explanation:'Communication and follow-through are useful context. There is no universal duration that proves motive or safety.'},related:['boundaries-academy','emotional-influence','intermittent-reinforcement'],references:['cci','gross','coercion'],evidence:'An educational distinction based on communication, regulation, and control principles, not a diagnostic timing rule.'},
{id:'blame-shifting',number:14,module:'B',status:'full',title:'Blame-Shifting',definition:'Blame-shifting redirects responsibility for a relevant action onto someone or something else instead of addressing the person’s own contribution.',explanation:'Responsibility can genuinely be shared. A late project may reflect missing information, an unrealistic deadline, and an avoidable failure to communicate. The problem is not mentioning context; it is using a different complaint to avoid the original issue entirely. “You also made a mistake” does not answer whether a specific promise was broken. Conversely, a complaint may be mistaken or incomplete, so accountability should not mean forced acceptance of an accusation. Keep the inquiry narrow enough to examine evidence while allowing relevant context and proportionate responsibility.',mechanism:'Protecting a valued self-image can make criticism feel threatening. Attention then moves toward another person’s flaws or an external explanation. Others may join the new argument, leaving the initial action unresolved. This may be deliberate evasion, defensive habit, or confused conflict; the observable sequence is easier to establish than the motive.',examples:['Nora asks why a colleague missed an agreed update. The colleague responds only that Nora was unfriendly last month. Both issues may deserve discussion, but the second does not resolve the missing update.','A student explains that the shared file was inaccessible and acknowledges not reporting the problem. The account includes a constraint and ownership, rather than shifting all responsibility away.'],dialogue:['Nora: “We needed an update by noon.”','Colleague: “You were rude last month.”','Nora: “We can discuss that separately. What happened with today’s update?”'],notice:'Track the original question, the response, and whether a concrete account or repair follows. Look for recurring changes of subject and all-or-nothing stories in which one person never contributes to a problem. Check whether the initial accusation itself is accurate and specific.',not:'Explaining constraints, challenging a false allegation, or identifying shared responsibility is not automatically blame-shifting. Abuse is not a symmetrical communication failure simply because several people were present.',consequences:'Unresolved actions can recur because no one agrees on repair. The recipient may take excessive responsibility to end the argument. Overusing the label can also silence legitimate context or legitimate criticism of the original complainant.',tips:'Write two columns: the specific action and relevant context. Ask what each person could reasonably control. Separate distinct complaints, identify verifiable agreements, and discuss a feasible repair. In hierarchical or threatening settings, use suitable support rather than repeatedly attempting a private debate that leads to retaliation.',alternative:'“I missed the update. The file problem contributed, and I should have told you earlier. Next time I will send a brief notice” acknowledges context without surrendering accountability.',takeaways:['Context and responsibility can both matter.','Separate complaints need separate examination.','Repair is more useful than assigning a total character verdict.'],check:{difficulty:'Intermediate',prompt:'Which response combines context with accountability?',options:['The system failed, and I should have reported the delay sooner.','Your unrelated mistake means mine cannot matter.','Only one person can ever contribute to a conflict.'],correct:0,explanation:'The first response identifies a constraint and a controllable action. Accountability does not require pretending the system was irrelevant.'},related:['darvo-pattern','minimisation','behaviour'],references:['cci','openstax'],evidence:'Descriptive communication concept. Attribution and defensive responses are studied, but this label does not establish intent.'},
{id:'darvo-pattern',number:15,module:'B',status:'full',title:'DARVO',definition:'DARVO names a response sequence: Deny, Attack, and Reverse Victim and Offender. It describes how someone may respond when confronted about alleged harm.',explanation:'A person may deny the event, attack the complainant’s credibility, and present themselves as the primary victim of the complaint. Researchers examine how such responses may influence observers and self-blame. The acronym is not a lie detector. A person can be falsely accused, challenge evidence, or describe genuine harm without using the entire sequence. Identifying a resemblance does not establish that the original allegation is true. Evaluate the underlying conduct and the response as related but separate questions. A fair process should allow evidence and support without treating confidence, distress, or an acronym as a verdict.',mechanism:'Attention can shift from the alleged behaviour to the complainant’s supposed defects. Observers may then judge credibility using social status or emotional presentation rather than evidence. A complainant may become preoccupied with defending their character, leaving the initial concern unexamined. Research is developing, and effects depend on the situation and information available.',examples:['After an employee reports repeated insults, a supervisor denies any incident, calls the employee unstable, and says the complaint is persecution of the supervisor. The report and response both need independent examination.','A neighbour disputes a damage claim with dated photographs and asks for an impartial review without attacking the claimant. Denial alone is not the full DARVO pattern.'],dialogue:['Employee: “I want the repeated insults reviewed.”','Supervisor: “You are inventing this. You are the bully for reporting me.”','Adviser: “Let’s document the alleged incidents and assess each claim through the appropriate process.”'],notice:'Look for the sequence rather than one isolated phrase. Ask what evidence supports each allegation, whether character attacks substitute for facts, and whether there is retaliation. Consider power, access to witnesses, confidentiality, and the risks of public accusation.',not:'The acronym cannot diagnose a person, determine guilt, or remove the right to contest a complaint. Calling every defensive response DARVO may prevent fair assessment and can itself be used to discredit legitimate concerns.',consequences:'A reversal may discourage reporting, confuse observers, and increase self-doubt. A careless public label may also harm someone wrongly accused. Both risks support independent, evidence-sensitive processes rather than instant social-media judgments.',tips:'Keep a factual account when safe, distinguish observation from interpretation, and seek a suitable reporting or advocacy channel. Avoid trying to force an admission. Preserve relevant information without exposing others unnecessarily. Confidentiality and legal protections vary; do not promise either without checking.',alternative:'“I disagree with part of this account, but I will address the specific allegation and participate in an impartial review” allows challenge without substituting a personal attack.',takeaways:['A response pattern is not a guilt test.','Assess the allegation and response separately.','Independent evidence and fair process matter.'],check:{difficulty:'Advanced',prompt:'A response resembles DARVO. What conclusion is justified?',options:['The original allegation is automatically proved.','The response pattern deserves examination, while the allegation still requires evidence.','The accused person loses any right to reply.'],correct:1,explanation:'A pattern can affect communication and credibility judgments without proving the underlying facts. Fair assessment remains essential.'},related:['blame-shifting','gaslighting-academy','power'],references:['darvo','coercion'],evidence:'An emerging research framework, including Harsey and colleagues (2017), not a standardized forensic or clinical assessment.'},
{id:'triangulation',number:16,module:'B',status:'full',title:'Triangulation',definition:'In everyday relationship discussion, triangulation describes routing a two-person conflict through a third person in ways that can obscure communication or create alliances and pressure.',explanation:'The term has several meanings, including family-systems theory and a research method of comparing evidence. Here it refers to a communication pattern, not a universal explanation for families. Third-party involvement is often helpful: mediation, advocacy, translation, and safeguarding may be essential. Concern arises when an absent person’s supposed opinion replaces direct evidence, private information is selectively relayed, or people are pressured to compete for approval. “Everyone agrees with me” can make a dispute feel settled while preventing anyone from checking who said what. The useful question is how the third party is being used.',mechanism:'A third person can reduce the discomfort of a direct conversation, but may also carry selective messages between people. Group belonging and uncertainty can make an alleged consensus persuasive. Alliances may harden as each person hears a different account. These processes are possible, not proof that all indirect communication has a concealed motive.',examples:['A manager tells two employees separately that the other thinks their work is poor, while refusing any joint discussion or specific examples. Each begins defending themselves against an account they cannot check.','Two siblings ask an agreed mediator to help divide caring tasks. Everyone can speak, correct summaries, and decline proposed arrangements. Third-party involvement supports clarity rather than secret competition.'],dialogue:['Manager: “Your colleague agrees you are the problem.”','Employee: “What specific work issue needs addressing?”','Employee: “Can we use a shared review process rather than speak for someone absent?”'],notice:'Ask whether accounts can be checked, whether the third person consents to being quoted, and whether everyone can respond. Consider accessibility and safety: direct contact is not always desirable. Look for repeated selective disclosure and threats to belonging, not simply the presence of another person.',not:'Seeking trusted support, reporting harm, or using a mediator is not inherently manipulation. People in unsafe relationships should not be pressured into direct confrontation under the slogan of avoiding triangulation.',consequences:'Uncheckable messages can generate mistrust and isolate people from each other. A well-run third-party process can reduce escalation and make power differences visible. The same basic arrangement can therefore have very different ethical effects.',tips:'Request specific behaviour and avoid repeating private allegations as settled fact. Clarify what information may be shared. Where appropriate, use an agreed facilitator with clear roles. If joint discussion could expose someone to retaliation, choose a protected channel instead of insisting everyone meet.',alternative:'“I am not comfortable speaking for them. Let’s use a process where each account can be heard safely” resists manufactured consensus while preserving access to support.',takeaways:['Third-party involvement can help or harm.','Check whose account is being represented.','Direct contact is not always the safest solution.'],check:{difficulty:'Advanced',prompt:'Which third-party arrangement best supports clarity?',options:['Secretly quote an absent person to end all debate.','Use an agreed facilitator with transparent roles and room to correct accounts.','Forbid anyone from seeking outside support.'],correct:1,explanation:'Transparent facilitation differs from selective message-carrying. Safety and confidentiality still need planning.'},related:['social-proof','isolation-control','power'],references:['openstax','cci','coercion'],evidence:'Family-systems interpretations are theoretical and vary. This lesson teaches observable communication features rather than treating the term as a diagnosis.'},
{id:'projection',number:17,module:'B',status:'full',title:'Psychological Projection',definition:'Projection is a theoretical interpretation in which someone attributes their own unacceptable feelings, motives, or traits to another person.',explanation:'A person who feels competitive might repeatedly accuse a colleague of jealousy. That observation could fit projection, but it could also fit an accurate complaint, a misunderstanding, or many other explanations. The concept comes from psychodynamic traditions and has a broader popular use. Inferring an unconscious motive is much harder than observing an accusation. Avoid turning “you are projecting” into a way to dismiss feedback without checking it. You can address a false or hurtful accusation without proving why it was made. The quality of the evidence matters more than how psychologically sophisticated an explanation sounds.',mechanism:'In the theoretical account, attributing an unwanted feeling elsewhere protects a preferred view of oneself. Related research on defensive thinking and social judgment does not establish that every accusation reveals the accuser’s hidden trait. Similarity, stereotypes, prior experience, or actual evidence may also shape what someone perceives.',examples:['A student who worries about status calls every successful classmate arrogant without examples. Projection is one possible interpretation, but insecurity and hostile inference cannot be established from that sentence alone.','A colleague says a report contains an error and provides the relevant calculation. Calling the colleague insecure would avoid evaluating the calculation rather than explain it.'],dialogue:['Colleague: “You only want attention.”','Rae: “What specific behaviour are you concerned about?”','Rae: “I will discuss the behaviour, but I cannot verify a claim about hidden motives.”'],notice:'Separate an observable action, an attributed motive, and a theory about the person making the attribution. Look for relevant evidence and alternative explanations. Notice whether the label ends discussion rather than improving understanding. Repetition can justify a communication boundary without proving an unconscious mechanism.',not:'Projection is not a reliable rule that every accusation is a confession. It is not a diagnosis and cannot tell you whether a particular allegation is true. Disagreeing with criticism does not establish that it was projected.',consequences:'A tentative concept may support reflection on one’s own assumptions. Used as a certainty about others, it can encourage mind reading, invalidate concerns, and intensify conflict. People may become distracted from the practical issue they can actually examine.',tips:'Ask for examples and assess their accuracy. Try the reflective question “Am I assuming others share my motives?” without declaring a conclusion. If accusations continue without specifics, state what discussion you can participate in. Professional therapy may explore patterns, but an online exchange cannot establish them.',alternative:'“I may be bringing my own worries into this. Let’s check what happened” uses the idea for self-reflection instead of as an accusation that the other person cannot meaningfully answer.',takeaways:['Projection is an interpretation, not direct observation.','Accusations are not automatically confessions.','Check behaviour before inferring hidden motives.'],check:{difficulty:'Advanced',prompt:'Someone accuses a colleague of jealousy. Does this prove the accuser is jealous?',options:['Yes, accusations always reveal the same hidden trait.','No; projection is one hypothesis and the accusation needs independent assessment.','Only if the accuser sounds emotional.'],correct:1,explanation:'Neither the accusation nor emotional tone establishes an unconscious motive. Examine specific evidence and alternatives.'},related:['attribution-error','confirmation','blame-shifting'],references:['openstax'],evidence:'A historically influential psychodynamic concept with debated interpretation and difficult direct measurement. Popular certainty about identifying projection is not warranted.'},
{id:'boundary-testing',number:18,module:'B',status:'full',title:'Boundary Testing',definition:'Boundary testing describes repeated attempts to push a stated limit, especially after the limit has been understood and declined.',explanation:'Limits are not always initially clear. A person may ask for clarification, suggest a reasonable compromise, or accidentally forget a preference. The important distinction is whether negotiation allows a genuine no. A pattern of small exceptions can gradually turn a limit into something that must be defended each time. This can happen with borrowed money, workplace availability, privacy, or physical contact. The behaviour does not identify a personality type. Power and practical alternatives matter: someone may appear flexible because refusing risks their job or housing, not because they freely changed their mind.',mechanism:'Repeated requests can increase the effort of refusal. A small concession may establish a new expectation even when it was intended as an exception. Relief from persistent asking can make giving in appealing. These learning and effort processes are possible explanations, not evidence that a requester consciously planned an escalation.',examples:['After Ana says she does not share account passwords, a partner repeatedly asks for “just one login” and calls every refusal suspicious. The same limit is treated as evidence of disloyalty.','A colleague asks whether a deadline limit includes urgent safety incidents. They accept the clarification and use the agreed emergency route. Asking about scope differs from relentless pressure.'],dialogue:['Partner: “If you trust me, let me in just this once.”','Ana: “I do not share passwords, including as a trust test.”','Ana: “I can discuss the concern without giving account access.”'],notice:'Ask whether the limit was clear, whether the person acknowledged it, and what follows refusal. Notice pressure, ridicule, repeated “exceptions,” and material consequences. Also consider whether the boundary conflicts with genuine shared responsibilities that need negotiation rather than unilateral declaration.',not:'A request for clarification or a one-off misunderstanding is not enough to establish a manipulative pattern. A boundary is not a right to control every action of another adult. Accountability is not automatically an attack on a limit.',consequences:'Repeated pressure can consume attention, blur agreements, and teach someone that their no will not be accepted. A rigid refusal to discuss legitimate responsibilities can also harm coordination. Clarity and reciprocity help distinguish these situations.',tips:'State the limit and relevant scope once in specific terms. Identify an action you can safely take if pressure continues, such as using separate accounts or a formal work channel. Track actual follow-through rather than repeatedly debating your worth. Seek support before testing consequences where there are threats or dependency.',alternative:'“I understand the limit. Here is a different option that does not require you to change it” shows negotiation without making refusal morally unacceptable. Respect is visible in subsequent behaviour, not just agreement in the moment.',takeaways:['Clarification differs from repeated pressure.','Exceptions should remain voluntary.','Evaluate how a clear no is treated.'],check:{difficulty:'Intermediate',prompt:'Which detail most distinguishes boundary testing from clarification?',options:['The person asks one question about scope.','The person repeatedly pressures the same understood limit and punishes refusal.','The person accepts an alternative.'],correct:1,explanation:'Repetition after understanding, especially with punishment, is more informative than a single question about an unclear rule.'},related:['boundaries-academy','love-bombing','moving-goalposts'],references:['cci','coercion'],evidence:'A descriptive everyday term. Assertiveness and coercive-control guidance support assessing concrete behaviour rather than diagnosing a motive.'},
{id:'moving-goalposts',number:19,module:'B',status:'full',title:'Moving the Goalposts',definition:'Moving the goalposts means changing the criteria for success or acceptance after someone has tried to meet the previously stated criteria, without a fair explanation or process.',explanation:'Plans legitimately change when new evidence, risks, or responsibilities appear. Fair revision identifies what changed, why it matters, and how prior work will be treated. Concern arises when success becomes permanently unreachable: every completed task reveals a new hidden requirement, and the person judging it denies that any earlier agreement existed. In relationships this may look like endless demands to prove loyalty. At work it may look like unstable promotion standards. The pattern is easier to assess when expectations are explicit, but written criteria alone cannot eliminate unequal power or unfair discretion.',mechanism:'Uncertain standards can keep attention focused on the evaluator’s approval. Past effort may increase commitment to trying again, while hope of finally succeeding discourages reassessment. This can combine with sunk costs and intermittent praise. Changing standards may also reflect poor management rather than a deliberate plan; impact and accountability still matter.',examples:['A supervisor promises certification after a checklist is completed, then adds unrelated unpaid tasks each time it is finished. There is no explanation, review route, or stable endpoint.','A safety team adds a new test after discovering a genuine fault, explains the reason, credits completed work, and agrees on a revised timeline. This is a transparent change rather than evidence of a permanently rigged test.'],dialogue:['Worker: “We completed the agreed requirements.”','Supervisor: “Now you need to prove commitment another way.”','Worker: “Can we document the remaining criteria and the review process?”'],notice:'Compare earlier criteria with current ones. Ask what new information justifies revision, whether changes apply consistently, and whether success remains attainable. Look for repeated denial of agreements, vague loyalty tests, and absence of appeal. Consider whether the original expectation was actually shared.',not:'Every revision, increased skill level, or updated requirement is not manipulation. Learning often involves progressively harder work. The issue is transparency and fairness, not a promise that standards never change.',consequences:'Unstable criteria can create exhaustion, self-doubt, and wasted investment. People may accept increasingly costly demands to justify what they already spent. Calling any new feedback a moved goalpost can also block legitimate improvement.',tips:'Request specific criteria, dates, and a process for changes. Summarise agreements factually where safe. Set a review point for deciding whether further investment is worthwhile. Where the evaluator controls pay or essential opportunities, consider institutional advice rather than assuming a private challenge is safe.',alternative:'“A new requirement has emerged for this reason; here is what remains, how earlier work counts, and how you can question the change” makes revision accountable instead of converting acceptance into an endless test.',takeaways:['Standards can change fairly.','Hidden, repeated changes deserve scrutiny.','Past investment does not require endless continuation.'],check:{difficulty:'Intermediate',prompt:'Which revision best avoids moving-goalpost concerns?',options:['Add secret requirements whenever someone finishes.','Explain a newly discovered risk, credit completed work, and agree on revised criteria.','Replace written criteria with “prove you care.”'],correct:1,explanation:'A transparent reason and reviewable criteria distinguish legitimate revision from an unreachable or concealed standard.'},related:['sunk-cost','boundary-testing','power'],references:['cci','openstax'],evidence:'A communication and reasoning description, not a clinical construct. Learning, investment, and authority principles help explain possible effects.'},
{id:'double-binds',number:20,module:'B',status:'full',title:'Double Binds',definition:'A double bind describes incompatible demands in which responding to one expectation violates another, particularly when clarification or leaving is also blocked.',explanation:'A manager may demand independent thinking but punish any decision not approved in advance. A family member may require affection to be spontaneous and then demand it on command. Difficult trade-offs are common; not all are double binds. The defining educational concern is an impossible or contradictory standard combined with little room to name the contradiction. The concept has a history in communication theory. Historical claims linking family double binds as a sufficient cause of schizophrenia are not accepted explanations and should not be used to blame families or diagnose illness.',mechanism:'Conflicting expectations make error unavoidable. If asking for clarification also brings criticism, people may devote energy to guessing which demand matters this time. Power and dependency can make departure unrealistic. Such conditions can produce anxiety and hesitation without implying a unique disease mechanism or a deliberate conspiracy.',examples:['A junior designer is told to show initiative, but each independent choice is punished for not obtaining approval. Asking for approval is then criticised as dependence. The process needs clarification, not a character verdict.','A student must choose between two valuable events scheduled together. That is a real trade-off, but nobody punishes the student for naming the conflict or choosing one.'],dialogue:['Designer: “You asked for independent decisions and advance approval.”','Manager: “Stop making excuses.”','Designer: “Can we specify which decisions I can make and which need approval?”'],notice:'Identify the exact demands, whether both can be met, and what happens when the inconsistency is raised. Look for blocked clarification, shifting criticism, and lack of an exit. Consider whether apparently conflicting instructions actually apply to different tasks or circumstances.',not:'A hard choice, disagreement, or two legitimate competing responsibilities is not automatically a double bind. This concept cannot explain a person’s diagnosis, and it does not prove the other party consciously designed the contradiction.',consequences:'People may delay decisions, hide uncertainty, or feel incapable because every outcome brings criticism. Naming the conflict can improve coordination in safe settings. In punitive environments, repeatedly pointing out contradictions can instead increase exposure.',tips:'Write the competing expectations as concrete actions. Ask which takes priority and request a feasible scope for discretion. Propose one testable agreement rather than debating motives. Where clarification leads to retaliation, seek a trusted representative or appropriate support channel. Protect safety before attempting a confrontation.',alternative:'“You may decide within this budget; ask for approval above it” replaces incompatible expectations with an explicit decision rule. Accepting that some goals conflict allows negotiation rather than assigning blame for an impossible task.',takeaways:['Contradictory demands need clarification.','Blocked discussion changes the power of a contradiction.','Historical disease claims should not be treated as fact.'],check:{difficulty:'Advanced',prompt:'What best distinguishes a double-bind concern from an ordinary trade-off?',options:['Two attractive options exist.','Demands conflict and even naming the contradiction is punished or blocked.','A task requires effort.'],correct:1,explanation:'Incompatibility plus restricted clarification is central here. A difficult choice alone does not establish a double bind.'},related:['moving-goalposts','power','boundaries-academy'],references:['openstax','cci'],evidence:'A communication-theory framework with contested historical extensions. It is not a supported sufficient cause of schizophrenia or a diagnostic tool.'},
{id:'isolation-control',number:21,module:'B',status:'full',title:'Social Isolation and Coercive Control',definition:'Coercive control is a pattern that restricts another person’s freedom through controlling or coercive conduct. Isolation can reduce access to relationships, resources, and independent perspectives.',explanation:'Concern is broader than one unpleasant conversation. Monitoring communications, limiting transport, taking documents, controlling money, and threatening consequences for contact may combine across everyday life. A person can appear to agree while navigating dependence or avoiding escalation. Social isolation also has other causes, including illness, poverty, migration, and inaccessible services. Do not assume that loneliness proves a controlling partner, or that someone who still has friends cannot be controlled. Practical access and freedom to use support matter more than counting contacts. Legal definitions and available protections differ across jurisdictions.',mechanism:'When independent resources and perspectives become harder to reach, challenging a controlling account can become more costly. Financial dependence, surveillance, and credible threats can make a nominal choice unrealistic. Restriction may escalate gradually or fluctuate. No universal timeline predicts what will happen next, and an educational checklist cannot create an individualized safety assessment.',examples:['A partner keeps Sana’s travel documents and reviews messages, then threatens eviction if she contacts her sister. Control involves resources and consequences, not merely a preference for private time together.','A person with limited mobility loses contact with friends because transport is inaccessible. They need practical access and support; assuming an abusive relationship would miss the stated barrier.'],dialogue:['Sana: “I would like to speak privately with someone about my options.”','Advocate: “What contact method is safe for you?”','Sana: “Please do not call the shared phone.”'],notice:'Ask about patterns, power, access to money and documents, monitoring, threats, and safe contact methods. Respect the person’s account and pace. Apparent compliance, returning to a relationship, or delayed disclosure does not establish that restrictions were freely chosen.',not:'Wanting time together, negotiating shared finances, or one argument is not enough to establish coercive control. Nor is this solely a communication problem that equal politeness can solve. Avoid diagnoses and unsupported predictions about future violence.',consequences:'Restrictions can affect safety, employment, health access, confidence, and support networks. Leaving or disclosing can carry risks as well as benefits. Pressure from helpers to take one immediate action may unintentionally remove more agency.',tips:'If helping, ask what support feels useful and safe, avoid secret promises you cannot keep, and offer local specialist resources. If affected, consider confidential safety planning where accessible. Do not store plans on monitored devices without assessing risk. In immediate danger, use appropriate emergency help if safe to do so.',alternative:'Healthy interdependence preserves access to independent relationships, resources, privacy, and disagreement. Shared decisions are negotiated without threats to essential needs, and neither person must earn basic freedom through compliance.',takeaways:['Assess patterns across daily life.','Nominal choice may hide serious constraints.','Support should restore agency and consider safety.'],check:{difficulty:'Advanced',prompt:'Which helping response best preserves agency when control is suspected?',options:['Demand immediate departure regardless of risk.','Ask about safe contact, listen to preferences, and offer confidential specialist support.','Contact the suspected controller to settle the dispute.'],correct:1,explanation:'Safe, person-led support is preferable to actions that may expose someone to retaliation. Urgent danger may require emergency support.'},related:['coercion','gaslighting-academy','emotional-blackmail'],references:['coercion','sweet'],evidence:'Grounded in authoritative coercive-control guidance. Legal thresholds and safety plans require jurisdiction-specific expertise.'},
{id:'intermittent-reinforcement',number:22,module:'B',status:'full',title:'Intermittent Reinforcement',definition:'Intermittent reinforcement occurs when a behaviour is followed by a reinforcing consequence on some occasions rather than every time.',explanation:'Learning research distinguishes different schedules of reinforcement. Behaviour learned with occasional reward can persist when reward becomes unavailable, depending on the schedule and history. Popular relationship accounts sometimes turn this into a guaranteed explanation for attachment to inconsistent partners. That leap is too strong. Human relationships involve meanings, dependency, affection, threats, practical constraints, and many other influences. Inconsistent warmth may be relevant without proving an intentional conditioning programme. Evaluate the behaviour and its effects rather than assuming that every confusing relationship can be reduced to a laboratory schedule.',mechanism:'When an outcome has been unpredictable, an unrewarded attempt may not signal that future attempts will fail. Persistence can therefore continue. Reward timing, prior learning, motivation, and alternatives affect the result. Negative reinforcement is different: it increases behaviour by removing something aversive, rather than meaning punishment or “bad reinforcement.”',examples:['A student keeps checking a club page because useful opportunities appear unpredictably. Occasional relevant posts help maintain checking even during quiet weeks.','After repeated insults, a partner sometimes becomes affectionate when Ren apologises for unrelated things. The pattern may encourage further appeasement, but housing dependence and fear also need examination before drawing conclusions about why Ren stays.'],dialogue:['Ren: “I keep hoping the warm days will return.”','Friend: “Those moments matter to you. How does the whole pattern affect you?”','Ren: “I want help thinking about options without being told I am foolish.”'],notice:'Identify the behaviour, consequence, timing, and realistic alternatives. Ask whether the consequence actually increases the behaviour rather than calling any pleasant event reinforcement. In relationships, examine safety and resources alongside emotional patterns. A short description cannot isolate one learning mechanism.',not:'Intermittent reinforcement is not mind control. Inconsistency can arise from illness, workload, ambivalence, or ordinary variation. It does not establish a diagnosis, deliberate abuse, or a complete explanation of attachment.',consequences:'Unpredictable rewards can sustain checking, spending, or repeated attempts at approval. People may blame themselves for persisting. Oversimplified explanations can obscure the material barriers and choices that shape someone’s situation.',tips:'Review the overall pattern rather than only the most recent good or bad moment. In low-risk settings, reduce disruptive cues and make valued alternatives easier to access. For relationship concerns, identify support and practical resources; do not assume changing a reward schedule is an appropriate way to manage another adult.',alternative:'Consistent, transparent agreements and care that does not depend on surrendering limits support healthier relationships. Discuss availability honestly rather than using withdrawal and reward as tools to obtain compliance.',takeaways:['Intermittent refers to timing, not moral quality.','Learning principles do not explain every relationship.','Assess the whole pattern and available alternatives.'],check:{difficulty:'Intermediate',prompt:'What makes an outcome a reinforcer in learning terminology?',options:['It is labelled a reward by the giver.','It increases the future likelihood of the relevant behaviour.','It feels morally positive to an observer.'],correct:1,explanation:'Reinforcement is defined by its effect on behaviour, not by intention or a moral label. That effect requires observation.'},related:['behaviour','love-bombing','sunk-cost'],references:['openstax','coercion'],evidence:'Reinforcement schedules are established learning concepts. Applying them as a complete relationship explanation is an educational simplification that requires caution.'},
{id:'minimisation',number:23,module:'B',status:'full',title:'Minimisation and Denial',definition:'Minimisation downplays the significance or impact of an event. Denial rejects that an event or claim is true. Neither term by itself tells us whether a disputed account is accurate.',explanation:'Someone may say a comment was “just a joke” while ignoring its repeated humiliating effect. Another person may deny an accusation because it is false. A careful response distinguishes what happened, how it affected people, and what explanation is being offered. Intent and impact can differ: a person may not have meant harm and still need to repair it. Equally, impact does not automatically verify every factual interpretation. Look for openness to specifics, willingness to correct mistakes, and whether repeated concerns are made impossible to discuss.',mechanism:'Threats to self-image can encourage defensive reinterpretation. Shared norms may normalise conduct so that its effects are overlooked. Denial may also reflect genuine memory differences or missing information. A protective explanation can become problematic when it prevents any evidence from counting or makes another person’s experience categorically irrelevant.',examples:['A teammate repeatedly mocks Kiran’s accent, then says everyone is too sensitive when asked to stop. The response bypasses the specific conduct and its impact.','Two neighbours disagree about whether a parcel was delivered. One checks a receipt and acknowledges the error. Initial denial followed by evidence-sensitive correction differs from a repeated reality-undermining pattern.'],dialogue:['Kiran: “The accent jokes make it harder for me to contribute.”','Teammate: “It was only a joke.”','Kiran: “You may have intended humour. I am asking you to stop those comments.”'],notice:'Look for specific acts, repetition, evidence, response to clarification, and practical repair. Ask whether “not serious” describes the speaker’s intention or dismisses consequences without examination. Consider cultural and language differences without assuming that a shared joke overrides an expressed limit.',not:'Denying a false claim is not inherently gaslighting. Disagreeing about severity is not automatically abuse. A person can make a genuine mistake, listen, and change. No emotional reaction is a reliable truth test.',consequences:'Repeated dismissal can discourage reporting and leave problems unresolved. People may doubt whether they deserve help. Treating all denial as proof of wrongdoing can also undermine fair assessment and make ordinary disagreement unsafe.',tips:'Separate event, impact, intention, and requested change in your notes or discussion. Ask for a concrete response rather than an admission about character. If safe, use a factual example and a feasible boundary. Where concerns involve harassment or retaliation, seek the appropriate support or reporting route rather than relying entirely on repeated informal requests.',alternative:'“I did not intend that effect, but I understand the concern and will stop” allows responsibility without pretending intent and impact are identical. “I recall it differently; let’s check” permits evidence without humiliation.',takeaways:['Intent does not erase impact.','Denial is not automatically deception.','Specific repair matters more than a label.'],check:{difficulty:'Intermediate',prompt:'Which response best addresses an unintended harmful comment?',options:['It was not intended, so no response is needed.','Acknowledge the impact, examine the conduct, and agree on a concrete change.','Assume the listener’s feelings prove every factual allegation.'],correct:1,explanation:'Accountability can consider both intent and impact without confusing a feeling with proof of every detail.'},related:['gaslighting-academy','blame-shifting','boundaries-academy'],references:['cci','coercion','sweet'],evidence:'Descriptive communication concepts. Broader gaslighting or abuse conclusions require patterns, context, and evidence.'},
{id:'shame-pressure',number:24,module:'B',status:'full',title:'Shame-Based Pressure',definition:'Shame-based pressure pushes behaviour by attacking a person’s worth, identity, or belonging rather than addressing a specific action and a proportionate remedy.',explanation:'“You missed this task” names behaviour. “You are useless unless you do this” makes worth conditional on compliance. Shame and guilt overlap in everyday language, but a useful educational distinction is between a negative evaluation of the self and concern about a particular action. Shame is not always caused by another person, and not every uncomfortable correction is shaming. Public criticism, status differences, cultural expectations, and prior experiences can change how a message is received. Accountability can be firm without degrading a person’s basic dignity.',mechanism:'Threats to belonging or identity can draw attention toward hiding, appeasing, or defending the self. That may reduce the capacity to examine the actual problem. A person might comply briefly to escape humiliation without learning a workable alternative. Responses vary; no single emotional process follows every critical statement.',examples:['A coach calls a teenager worthless in front of the team until they agree to train while injured. Identity attack and pressure combine with a health risk.','A tutor privately explains that copying text without citation breaks an academic rule, offers a chance to learn citation, and states the relevant consequence. Clear accountability need not become an attack on personal worth.'],dialogue:['Coach: “Only weak people need rest.”','Student: “I need the injury assessed, not a judgment about my character.”','Student later asks a trusted adult about a safe training plan.'],notice:'Ask whether criticism identifies a specific action, offers a realistic remedy, and preserves dignity. Notice public exposure, identity stereotypes, impossible standards, and withdrawal of belonging. Also examine whether embarrassment comes from being corrected rather than from degrading wording or conduct.',not:'Feeling ashamed does not prove that someone intended humiliation. A proportionate consequence is not automatically abusive. Avoid using the concept to erase responsibility for harm, misconduct, or legitimate obligations.',consequences:'Repeated degradation can discourage help-seeking and encourage secrecy or self-criticism. Short-term compliance may conceal distress or practical risk. Conversely, respectful correction can support learning even when it feels uncomfortable at first.',tips:'Translate global judgments into a specific behaviour and feasible next step. Ask for private feedback where safe and appropriate. If you hold authority, correct conduct without using identity or vulnerability as leverage. Seek support when humiliation is repeated, discriminatory, or connected to retaliation; a better script alone may not change the environment.',alternative:'“This action caused a problem; here is the standard and the support for meeting it” separates accountability from worth. A person can need to change behaviour while still deserving respect and protection.',takeaways:['Correct actions without attacking worth.','Discomfort alone does not prove humiliation.','Dignity and accountability can coexist.'],check:{difficulty:'Intermediate',prompt:'Which feedback best preserves dignity while requiring change?',options:['You are worthless unless you succeed.','This citation is missing; add the source and review the referencing guide.','A good person would never need instructions.'],correct:1,explanation:'Specific conduct, a clear standard, and a feasible remedy support learning without making worth conditional on compliance.'},related:['guilt-tripping','emotional-influence','power'],references:['cci','openstax','coercion'],evidence:'Shame and guilt are researched emotions, but their definitions and effects vary. This is a communication framework, not a clinical assessment.'}
];
